int32_t compute_error(int32_t current_temp, int32_t low_threshold, int32_t high_threshold) {
    if (current_temp > high_threshold) {
        return current_temp - high_threshold;
    } else if (current_temp < low_threshold) {
        return low_threshold - current_temp;
    } else {
        return 0;
    }
}

